import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Import Axios for API calls

const AddExpense = ({ tripId, setExpenses }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState('');
  const [familyHeads, setFamilyHeads] = useState([]);

  // Fetch family heads from the backend when component mounts
  useEffect(() => {
    const fetchFamilyHeads = async () => {
      try {
        const response = await axios.get(`/trips/${tripId}/families`);
        const heads = response.data.families.map(family => ({
          name: family.head,
          label: `${family.head} (Head)`
        }));
        setFamilyHeads(heads);
      } catch (error) {
        console.error('Error fetching family heads:', error);
      }
    };

    if (tripId) {
      fetchFamilyHeads();
    }
  }, [tripId]);

  const handleAddExpense = async () => {
    if (!description || !amount || !paidBy) return;

    const newExpense = {
      description,
      amount: parseFloat(amount),
      paidBy,
    };

    try {
      const response = await axios.post(`/trips/${tripId}/expenses`, newExpense);
      // Assuming the backend responds with the updated expense list
      setExpenses((prev) => [...prev, response.data]);

      // Reset form
      setDescription('');
      setAmount('');
      setPaidBy('');
    } catch (error) {
      console.error('Error adding expense:', error);
    }
  };

  const styles = {
    container: {
      border: '1px solid #ccc',
      padding: '15px',
      borderRadius: '8px',
      marginBottom: '20px',
    },
    heading: {
      fontSize: '18px',
      fontWeight: 'bold',
      marginBottom: '10px',
    },
    input: {
      marginRight: '10px',
      padding: '6px',
      borderRadius: '4px',
      border: '1px solid #ccc',
    },
    button: {
      padding: '6px 12px',
      borderRadius: '4px',
      border: 'none',
      backgroundColor: '#007bff',
      color: 'white',
      cursor: 'pointer',
    },
  };

  return (
    <div style={styles.container}>
      <div style={styles.heading}>Add Expense</div>
      <input
        type="text"
        placeholder="Description"
        style={styles.input}
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <input
        type="number"
        placeholder="Amount"
        style={styles.input}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <select
        style={styles.input}
        value={paidBy}
        onChange={(e) => setPaidBy(e.target.value)}
      >
        <option value="">Select Payer</option>
        {familyHeads.map((head, idx) => (
          <option key={idx} value={head.name}>
            {head.label}
          </option>
        ))}
      </select>
      <button style={styles.button} onClick={handleAddExpense}>
        Add
      </button>
    </div>
  );
};

export default AddExpense;
